const analyser_les_produits = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: 'Analyser les produits', parameters: { jsCode: 'function attr(bloc, nom) {\n  const m = bloc.match(new RegExp(\'data-analytics_product_\' + nom + \'="([^"]*)"\'));\n  return m ? m[1] : null;\n}\nfunction nombreFr(v) {\n  if (v === null || v === undefined) return null;\n  const n = Number(String(v).replace(/[\\s\\u00a0]/g, \'\').replace(\',\', \'.\'));\n  return Number.isFinite(n) ? n : null;\n}\n\nconst produits = [];\nconst vus = new Set();\nconst erreurs = [];\nlet totalAnnonce = null;\nlet pagesOk = 0;\nlet pagesEchouees = 0;\n\nfor (const item of $input.all()) {\n  const page = item.json.data || item.json;\n  const categorie = item.json.categorie || (page.metadata && page.metadata.sourceURL) || \'inconnue\';\n  const html = page.rawHtml || item.json.rawHtml;\n  if (!html || typeof html !== \'string\' || html.length < 1000) {\n    pagesEchouees += 1;\n    erreurs.push(\'Page non recuperee : \' + categorie);\n    continue;\n  }\n  pagesOk += 1;\n\n  const nomsParUrl = new Map();\n  for (const m of html.matchAll(/<script type="application\\/ld\\+json">([\\s\\S]*?)<\\/script>/g)) {\n    const corps = m[1];\n    if (corps.indexOf(\'"ItemList"\') === -1) continue;\n    try {\n      const obj = JSON.parse(corps.trim());\n      if (obj.numberOfItems) {\n        const n = Number(obj.numberOfItems);\n        if (Number.isFinite(n) && n > 0 && (totalAnnonce === null || n > totalAnnonce)) totalAnnonce = n;\n      }\n      for (const it of obj.itemListElement || []) {\n        if (it && it.url && it.name) nomsParUrl.set(String(it.url).replace(/\\\\u0026/g, \'&\'), String(it.name).trim());\n      }\n    } catch (e) { /* bloc illisible : ignore */ }\n  }\n\n  const cartes = html.split(/(?=<li[^>]*class="[^"]*product-list__item[^"]*"[^>]*data-product-id=)/).slice(1);\n  if (cartes.length === 0) erreurs.push(\'Aucune fiche trouvee sur \' + categorie);\n  let ajoutes = 0;\n  for (const carte of cartes) {\n    const id = (carte.match(/data-product-id="(\\d+)"/) || [])[1] || null;\n    if (!id || vus.has(id)) continue;\n    const chemin = (carte.match(/href=["\\x27][^"\\x27]*(\\/ref\\/\\d+)["\\x27]/) || [])[1] || (\'/ref/\' + id);\n    vus.add(id);\n    ajoutes += 1;\n    const url = chemin.indexOf(\'http\') === 0 ? chemin : \'https://www.boulanger.com\' + chemin;\n\n    const aria = (carte.match(/class="price__crossed"[^>]*aria-label="oldPrice\\s*([\\d\\s,.\\u00a0]+)/) || [])[1] || null;\n    const blocDel = (carte.match(/<del class="price__crossed"[\\s\\S]{0,300}?<\\/del>/) || [])[0] || null;\n    const ancienBrut = aria || (blocDel ? ((blocDel.match(/(\\d[\\d\\s,.\\u00a0]*,\\d{2})/) || [])[1] || null) : null);\n\n    const blocPrix = (carte.match(/<p class="price__amount">([\\s\\S]{0,120}?)<\\/p>/) || [])[1] || null;\n    const prixBrut = blocPrix ? ((blocPrix.match(/(\\d[\\d\\s,.\\u00a0]*,\\d{2})/) || [])[1] || null) : null;\n    const prix = nombreFr(prixBrut) !== null ? nombreFr(prixBrut) : nombreFr(attr(carte, \'unitprice_ati\'));\n\n    const remise = nombreFr(attr(carte, \'discount_value\'));\n    produits.push({\n      marque: (attr(carte, \'brand\') || \'\').trim() || \'Marque inconnue\',\n      nomProduit: nomsParUrl.get(url) || \'\',\n      reference: String(id),\n      prixActuel: prix,\n      ancienPrix: nombreFr(ancienBrut),\n      reduction: remise !== null && remise > 0 ? remise : null,\n      enPromotion: remise !== null && remise > 0,\n      url: url\n    });\n  }\n  erreurs.push(\'Page \' + categorie + \' : \' + cartes.length + \' fiches rendues, \' + ajoutes + \' references nouvelles\');\n}\n\n// Section 7 de la spec : le total annonce par le site est le seul juge de completude.\nlet statut = \'Echec\';\nif (produits.length > 0) {\n  const complet = pagesEchouees === 0 && (totalAnnonce === null || produits.length >= totalAnnonce);\n  statut = complet ? \'Collecte complete\' : \'Collecte partielle\';\n  if (totalAnnonce !== null && produits.length < totalAnnonce) {\n    erreurs.push(\'Couverture incomplete : \' + produits.length + \' produits recuperes sur \' + totalAnnonce + \' annonces par le site.\');\n  }\n}\n\nreturn [{ json: {\n  dateCollecte: new Date().toISOString().slice(0, 10),\n  enseigne: \'Boulanger\',\n  produits: produits,\n  statut: statut,\n  pagesOk: pagesOk,\n  pagesEchouees: pagesEchouees,\n  totalAnnonce: totalAnnonce,\n  erreurs: erreurs.slice(0, 20)\n} }];' }, position: [672, 96], notes: 'Parseur deterministe, sans LLM : impossible d inventer une donnee. Nom depuis le JSON-LD ItemList, marque et reference depuis data-analytics_product_brand et data-product-id, prix actuel depuis data-analytics_product_unitprice_ati, ancien prix depuis l aria-label oldPrice du <del class=price__crossed>, remise depuis data-analytics_product_discount_value. L URL est derivee de l identifiant, donc independante de la forme du href. Compare le nombre de produits obtenus au total annonce pour ne jamais presenter une collecte partielle comme complete.', notesInFlow: true }
});

