const statistiques_par_marque = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: 'Statistiques par marque', parameters: { jsCode: 'const d = $(\'Analyser les produits\').first().json;\n\nconst regroupement = new Map();\nfor (const p of d.produits || []) {\n  const marque = (p.marque || \'\').toString().trim() || \'Marque inconnue\';\n  if (!regroupement.has(marque)) regroupement.set(marque, { produits: 0, promos: 0, reductions: [], prix: [] });\n  const s = regroupement.get(marque);\n  s.produits += 1;\n  if (p.enPromotion === true) s.promos += 1;\n  if (typeof p.reduction === \'number\') s.reductions.push(p.reduction);\n  if (typeof p.prixActuel === \'number\') s.prix.push(p.prixActuel);\n}\n\nfunction moyenne(liste) {\n  return liste.length ? Math.round((liste.reduce((a, b) => a + b, 0) / liste.length) * 10) / 10 : null;\n}\n\nconst stats = [];\nfor (const [marque, s] of regroupement) {\n  stats.push({\n    marque: marque,\n    produits: s.produits,\n    promotions: s.promos,\n    tauxPromo: s.produits ? Math.round((s.promos / s.produits) * 1000) / 10 : null,\n    reductionMoyenne: moyenne(s.reductions),\n    reductionMax: s.reductions.length ? Math.max.apply(null, s.reductions) : null,\n    prixMoyen: moyenne(s.prix)\n  });\n}\nstats.sort((a, b) => b.produits - a.produits || a.marque.localeCompare(b.marque));\n\nreturn [{ json: {\n  dateCollecte: d.dateCollecte,\n  enseigne: d.enseigne,\n  statut: d.statut,\n  pagesOk: d.pagesOk,\n  pagesEchouees: d.pagesEchouees,\n  totalAnnonce: d.totalAnnonce,\n  erreurs: d.erreurs,\n  totalProduits: (d.produits || []).length,\n  stats: stats\n} }];' }, position: [1120, 0], notes: 'Section 5 de la spec : nombre de produits, produits en promotion, reduction moyenne et reduction maximum, plus le taux de promotion et le prix moyen du tableau de la section 10. Une statistique sans donnee source reste nulle, elle n est pas estimee. Lit la collecte par reference explicite.', notesInFlow: true }
});

