const comparer_avec_la_semaine_precedente = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: 'Comparer avec la semaine precedente', parameters: { jsCode: 'const d = $(\'Analyser les produits\').first().json;\nconst historique = $input.all().map((i) => i.json);\n\nfunction cle(p) {\n  const ref = (p.reference || \'\').toString().trim().toLowerCase();\n  if (ref) return \'ref:\' + ref;\n  const url = (p.url || \'\').toString().trim().toLowerCase();\n  if (url) return \'url:\' + url;\n  return \'nom:\' + (p.nomProduit || p.nom_produit || \'\').toString().trim().toLowerCase();\n}\n\nconst parDate = new Map();\nfor (const h of historique) {\n  if (!h || typeof h !== \'object\') continue;\n  const date = (h.date_collecte || \'\').toString().trim();\n  if (!date || date === d.dateCollecte) continue;\n  if (!parDate.has(date)) parDate.set(date, new Map());\n  parDate.get(date).set(cle(h), h);\n}\nconst dates = Array.from(parDate.keys()).sort();\nconst semainePrecedente = dates.length ? dates[dates.length - 1] : null;\nconst precedent = semainePrecedente ? parDate.get(semainePrecedente) : new Map();\n\nconst courantMap = new Map();\nfor (const p of d.produits || []) courantMap.set(cle(p), p);\n\nconst nouveaux = [];\nconst disparus = [];\nconst changements = [];\nconst nouvellesPromos = [];\nconst promosTerminees = [];\n\nfor (const [k, p] of courantMap) {\n  const libelle = p.nomProduit || p.reference || \'(sans nom)\';\n  if (!precedent.has(k)) { nouveaux.push(libelle); continue; }\n  const old = precedent.get(k);\n  const prixAvant = typeof old.prix_actuel === \'number\' ? old.prix_actuel : null;\n  const prixApres = typeof p.prixActuel === \'number\' ? p.prixActuel : null;\n  if (prixAvant !== null && prixApres !== null && prixAvant > 0 && prixApres !== prixAvant) {\n    changements.push({ produit: libelle, ancienPrix: prixAvant, nouveauPrix: prixApres, variationPourcent: Math.round(((prixApres - prixAvant) / prixAvant) * 1000) / 10 });\n  }\n  const promoAvant = old.en_promotion === true;\n  const promoApres = p.enPromotion === true;\n  if (promoApres && !promoAvant) nouvellesPromos.push(libelle);\n  if (!promoApres && promoAvant) promosTerminees.push(libelle);\n}\n\nfor (const [k, h] of precedent) {\n  if (!courantMap.has(k)) disparus.push(h.nom_produit || h.reference || \'(sans nom)\');\n}\n\nreturn [{ json: {\n  semainePrecedente: semainePrecedente,\n  nbCollectesHistoriques: dates.length,\n  nouveaux: nouveaux,\n  disparus: disparus,\n  changements: changements,\n  nouvellesPromos: nouvellesPromos,\n  promosTerminees: promosTerminees\n} }];' }, position: [2016, 160], notes: 'Section 6 de la spec : nouveaux produits, produits disparus, changements de prix, nouvelles promotions et promotions terminees, par rapport a la seule collecte la plus recente anterieure. L historique arrive en entree, la collecte courante est lue par reference explicite. Le jour courant est exclu ici, pas par un filtre amont.', notesInFlow: true }
});

